function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is an integer from 1 to 10^5.';
  const gcd = (a, b) => { while (b !== 0) { const r = a % b; a = b; b = r; } return a; };
  const stack = [];
  for (const num of nums) {
    let current = num;
    while (stack.length > 0) {
      const d = gcd(stack[stack.length - 1], current);
      if (d === 1) break;
      current = (stack.pop() / d) * current;
      if (current > 1e8) return 'Every value of the final array must be at most 10^8.';
    }
    stack.push(current);
  }
  return null;
}

