function generate(rand, size) {
  const LIMIT = 1e8;
  const gcd = (a, b) => { while (b !== 0) { const r = a % b; a = b; b = r; } return a; };
  // Divisors of 21621600 = 2^5 * 3^3 * 5^2 * 7 * 11 * 13 merge often but their LCMs stay small.
  const M = 21621600;
  const smooth = [];
  for (let d = 2; d <= 100000; d++) if (M % d === 0) smooth.push(d);
  const primes = [7919, 49999, 99989, 99991, 65537, 31, 37, 41];
  const pickFrom = list => list[Math.floor(rand() * list.length)];
  const pick = () => {
    const r = rand();
    if (size === 'small') {
      if (r < 0.5) return 1 + Math.floor(rand() * 12);
      if (r < 0.75) return pickFrom(smooth.filter(v => v <= 60));
      if (r < 0.9) return 1 + Math.floor(rand() * 100000);
      return pickFrom(primes);
    }
    if (r < 0.3) return 1 + Math.floor(rand() * 100000);
    if (r < 0.65) return pickFrom(smooth);
    if (r < 0.8) return 1 + Math.floor(rand() * 30);
    if (r < 0.9) return 1;
    return pickFrom(primes);
  };
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 9);
  // Build the array while simulating the merges, so every final value stays within 10^8.
  const stack = [];
  const nums = [];
  const fits = value => {
    let current = value;
    for (let i = stack.length - 1; i >= 0; i--) {
      const d = gcd(stack[i], current);
      if (d === 1) return [i + 1, current];
      current = (stack[i] / d) * current;
      if (current > LIMIT) return null;
    }
    return [0, current];
  };
  for (let k = 0; k < n; k++) {
    let value = 1;
    let fit = null;
    for (let attempt = 0; attempt < 20 && !fit; attempt++) {
      value = pick();
      fit = fits(value);
    }
    if (!fit) { value = 1; fit = [stack.length, 1]; }
    stack.length = fit[0];
    stack.push(fit[1]);
    nums.push(value);
  }
  return [nums];
}
